// Mirrors the auto-username logic in the `handle_new_user` DB trigger so we can
// detect whether a username was auto-generated (i.e. the user hasn't chosen one).
export function generateAutoUsername(meta: Record<string, unknown>): string {
  let base =
    (meta.user_name as string) ||
    (meta.full_name as string) ||
    (meta.name as string) ||
    'poet'

  base = base.toLowerCase().replace(/[^a-z0-9_]/g, '')
  if (base.length < 3) base = 'poet'
  if (base.length > 24) base = base.slice(0, 24)
  return base
}

// True if `username` matches what the trigger would have produced, including the
// dedupe suffix (`_1`, `_2`, …) it appends on a collision.
export function looksAutoGenerated(
  username: string,
  meta: Record<string, unknown>
): boolean {
  const base = generateAutoUsername(meta)
  return username === base || new RegExp(`^${escapeRegExp(base)}_\\d+$`).test(username)
}

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

export const USERNAME_FLAG_KEY = 'poem_username_set'
